    if (start) {
      wave = start;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      preview = makeWave(wave + 1);
      const actions = strategy.plan(stateView());
      if (Array.isArray(actions)) {
        const count = Math.min(32, actions.length);
        for (let ai = 0; ai < count; ai++) {
          const a = actions[ai];
          if (!a || typeof a.slot !== "number" || a.slot < 0 || a.slot >= 16 || Math.floor(a.slot) !== a.slot) continue;
          const s = slots[a.slot];
          if (a.op === "build" && !s.turret && costs[a.type] !== undefined && gold >= costs[a.type]) {
            const type = a.type;
            gold -= costs[type];
            s.turret = { type: type, tier: 1, spent: costs[type], damage: damages[type], range: ranges[type], cooldown: 0 };
            const ti = turretNames.indexOf(type);
            log.push([tick, "B", a.slot, ti]);
            events.push({ kind: "build", slot: a.slot, type: type, x: s.x, y: s.y });
          } else if (a.op === "upgrade" && s.turret && s.turret.tier < 3) {
            const t = s.turret;
            const cost = costs[t.type] * t.tier;
            if (gold >= cost) {
              gold -= cost;
              t.spent += cost;
              t.tier++;
              t.damage = Math.floor(t.damage * 16 / 10);
              t.range += 30;
              log.push([tick, "U", a.slot, t.tier]);
              events.push({ kind: "upgrade", slot: a.slot, type: t.type, tier: t.tier, x: s.x, y: s.y });
            }
          } else if (a.op === "sell" && s.turret) {
            const t = s.turret;
            const refund = Math.floor(t.spent * 70 / 100);
            gold += refund;
            log.push([tick, "S", a.slot, 0]);
            events.push({ kind: "sell", slot: a.slot, type: t.type, tier: t.tier, x: s.x, y: s.y });
            s.turret = null;
          }
        }
      }
      const current = queuedWave;
      for (let i = 0; i < current.length; i++) spawnQueue.push({ tick: tick + 4 * i, wave: wave, index: i, type: current[i] });
      spawnQueue.sort(function (a,b) { return a.tick-b.tick || a.wave-b.wave || a.index-b.index; });
      queuedWave = preview;
    }
    while (spawnQueue.length && spawnQueue[0].tick === tick) {
      const q = spawnQueue.shift();
      const e = spawn(q.type, q.wave, 0);
      const p = pointAt(0, e.air);
      events.push({ kind: "spawn", id: e.id, type: q.type, wave: q.wave, x: p.x, y: p.y, air: e.air });
    }
    enemies.sort(function (a,b) { return a.id-b.id; });
    for (let i = 0; i < enemies.length; i++) {
      const e = enemies[i];
      e.progress += e.slow > 0 ? Math.floor(speeds[e.type] * 60 / 100) : speeds[e.type];
      if (e.progress >= routeLength(e.air)) {
        const p = pointAt(routeLength(e.air), e.air);
        base -= leaks[e.type];
        log.push([tick, "L", e.id, base]);
        events.push({ kind: "leak", id: e.id, type: e.type, x: p.x, y: p.y, hp: base });
        enemies.splice(i, 1);
        if (base <= 0) {
          fallTick = tick;
          log.push([tick, "F", wave, 0]);
          events.push({ kind: "fall", wave: wave, x: 2350, y: 1150 });
          replay.frames[tick] = frame();
          replay.endTick = tick;
          return result(tick);
        }
        i--;
      }
    }
    enemies.sort(function (a,b) { return a.id-b.id; });
    for (let i = 0; i < enemies.length; i++) {
      const e = enemies[i];
      e.age++;
      if (e.type === "mender" && e.age % 20 === 0) {
        const p = pointAt(e.progress, false);
        const amount = Math.floor(e.maxHp * 8 / 100);
        for (let j = 0; j < enemies.length; j++) {
          const other = enemies[j];
          const q = pointAt(other.progress, other.air);
          const dx = p.x - q.x, dy = p.y - q.y;
          if (dx * dx + dy * dy <= 150 * 150) other.hp = Math.min(other.maxHp, other.hp + amount);
        }
        events.push({ kind: "heal", id: e.id, x: p.x, y: p.y, radius: 150 });
      }
    }
    for (let si = 0; si < slots.length; si++) {
      const s = slots[si];
      const t = s.turret;
      if (!t) continue;
      if (t.cooldown > 0) {
        t.cooldown--;
        if (t.cooldown > 0) continue;
      }
      const candidates = [];
      for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i];
        if (e.hp <= 0) continue;
        if (t.type === "cannon" || t.type === "lance" ? e.air : t.type === "flak" ? !e.air : false) continue;
        const p = pointAt(e.progress, e.air);
        const dx = p.x - s.x, dy = p.y - s.y;
        if (dx * dx + dy * dy <= t.range * t.range) candidates.push(e);
      }
      candidates.sort(function (a,b) { return a.id-b.id; });
      if (!candidates.length) continue;
      let chosen = null;
      if (typeof strategy.target === "function") {
        const tv = { slot: s.slot, type: t.type, tier: t.tier, x: s.x, y: s.y, range: t.range };
        const cv = candidates.map(view);
        const id = strategy.target(tv, cv);
        for (let i = 0; i < candidates.length; i++) if (candidates[i].id === id) { chosen = candidates[i]; break; }
      }
      if (!chosen) {
        chosen = candidates[0];
        for (let i = 1; i < candidates.length; i++) {
          const cr = routeLength(candidates[i].air) - candidates[i].progress;
          const br = routeLength(chosen.air) - chosen.progress;
          if (cr < br) chosen = candidates[i];
        }
      }
      const cp = pointAt(chosen.progress, chosen.air);
      events.push({ kind: "shot", slot: s.slot, type: t.type, tier: t.tier, id: chosen.id, targetType: chosen.type, x: s.x, y: s.y, tx: cp.x, ty: cp.y, air: chosen.air, splash: splashes[t.type] });
      if (splashes[t.type] > 0) {
        const radius = splashes[t.type];
        for (let i = 0; i < enemies.length; i++) {
          const e = enemies[i];
          if (e.hp <= 0) continue;
          if (t.type === "cannon" ? e.air : !e.air) continue;
          const p = pointAt(e.progress, e.air);
          const dx = p.x - cp.x, dy = p.y - cp.y;
          if (dx * dx + dy * dy <= radius * radius) {
            const armor = e.type === "grunt" ? Math.floor(e.wave / 4) : e.type === "brute" ? 6 + e.wave : 0;
            e.hp -= Math.max(1, t.damage - armor);
          }
        }
      } else {
        const armor = chosen.type === "grunt" ? Math.floor(chosen.wave / 4) : chosen.type === "brute" ? 6 + chosen.wave : 0;
        chosen.hp -= t.type === "lance" ? t.damage : Math.max(1, t.damage - armor);
        if (t.type === "frost") chosen.slow = 30;
      }
      t.cooldown = periods[t.type];
      removeDead(s.slot, events);
      enemies.sort(function (a,b) { return a.id-b.id; });
    }
    for (let i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    replay.frames[tick] = frame();
  }
  replay.endTick = maxTicks;
  replay.frames[maxTicks] = replay.frames[maxTicks - 1];
  return result(maxTicks);
}
