{"path":"dev-strategy.js","content":"function createConfiguredStrategy(config) {
  const buildOrder = config.buildOrder;
  const upgradeOrder = config.upgradeOrder || buildOrder;
  const reserve = config.reserve || 0;
  const upgradeWave = config.upgradeWave || 8;
  const fullBuildWave = config.fullBuildWave || 0;
  const targetMode = config.targetMode || 0;
  return {
    plan(s) {
      const a = [];
      let gold = s.gold - (s.wave < 12 ? 0 : reserve);
      const built = [];
      for (let i = 0; i < s.slots.length; i++) if (s.slots[i].turret) built[s.slots[i].slot] = true;
      if (s.wave >= upgradeWave) {
        for (let pass = 0; pass < 2; pass++) {
          for (let i = 0; i < upgradeOrder.length; i++) {
            const slot = upgradeOrder[i];
            const t = s.slots[slot].turret;
            if (!t || t.tier !== pass + 1) continue;
            const base = t.type === 'bolt' ? 50 : t.type === 'cannon' ? 90 : t.type === 'frost' ? 70 : t.type === 'lance' ? 120 : 80;
            const cost = base * t.tier;
            if (gold >= cost) {
              a.push({op:'upgrade',slot:slot});
              gold -= cost;
              t.tier++;
            }
          }
        }
      }
      for (let i = 0; i < buildOrder.length; i++) {
        const item = buildOrder[i];
        const slot = typeof item === 'number' ? item : item[0];
        const type = typeof item === 'number' ? 'bolt' : item[1];
        if (built[slot]) continue;
        const cost = type === 'bolt' ? 50 : type === 'cannon' ? 90 : type === 'frost' ? 70 : type === 'lance' ? 120 : 80;
        if (gold >= cost) {
          a.push({op:'build',slot:slot,type:type});
          gold -= cost;
          built[slot] = true;
        }
      }
      return a;
    },
    target(t, c) {
      let best = c[0];
      let bestScore = -1e30;
      for (let i = 0; i < c.length; i++) {
        const e = c[i];
        let score = -e.remaining * 0.01;
        if (e.type === 'mender') score += targetMode === 2 ? 200 : 80;
        if (t.type === 'lance') {
          score += e.maxHp * 0.015 + e.armor * 2;
          if (e.type === 'brute') score += 70;
        } else if (t.type === 'frost') {
          score += e.speed * 2 + (e.slowed > 0 ? -120 : 40);
          if (e.type === 'brute') score += 20;
        } else if (t.type === 'cannon' || t.type === 'flak') {
          let cluster = 0;
          const radius = t.type === 'cannon' ? 90 : 70;
          for (let j = 0; j < c.length; j++) {
            const o = c[j];
            const dx = o.x-e.x, dy=o.y-e.y;
            if (dx*dx+dy*dy <= radius*radius) cluster += 1 + Math.min(o.hp, 150) / 100;
          }
          score += cluster * (targetMode === 1 ? 30 : 12);
        } else {
          if (e.hp <= (t.tier === 1 ? 26 : t.tier === 2 ? 41 : 65)) score += 25;
          if (e.type === 'wisp') score += 8;
        }
        if (score > bestScore) { bestScore = score; best = e; }
      }
      return best.id;
    }
  };
}
